package ec.edu.monster.modelo;
public class MovimientoModel { private String codigoCuenta,fechaMovimiento,codigoEmpleado,codigoTipoMovimiento,tipoDescripcion,cuentaReferencia,monedaOrigen; private int numeroMovimiento; private double importeMovimiento; private Double importeOrigen,tasaAplicada; public String getCodigoCuenta(){return codigoCuenta;} public void setCodigoCuenta(String v){codigoCuenta=v;} public int getNumeroMovimiento(){return numeroMovimiento;} public void setNumeroMovimiento(int v){numeroMovimiento=v;} public String getFechaMovimiento(){return fechaMovimiento;} public void setFechaMovimiento(String v){fechaMovimiento=v;} public String getCodigoEmpleado(){return codigoEmpleado;} public void setCodigoEmpleado(String v){codigoEmpleado=v;} public String getCodigoTipoMovimiento(){return codigoTipoMovimiento;} public void setCodigoTipoMovimiento(String v){codigoTipoMovimiento=v;} public String getTipoDescripcion(){return tipoDescripcion;} public void setTipoDescripcion(String v){tipoDescripcion=v;} public double getImporteMovimiento(){return importeMovimiento;} public void setImporteMovimiento(double v){importeMovimiento=v;} public String getCuentaReferencia(){return cuentaReferencia;} public void setCuentaReferencia(String v){cuentaReferencia=v;} public String getMonedaOrigen(){return monedaOrigen;} public void setMonedaOrigen(String v){monedaOrigen=v;} public Double getImporteOrigen(){return importeOrigen;} public void setImporteOrigen(Double v){importeOrigen=v;} public Double getTasaAplicada(){return tasaAplicada;} public void setTasaAplicada(Double v){tasaAplicada=v;} }
